import{_ as a,a0 as o,w as u,s,ao as l,I as r,x as n,a1 as e,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何擁有一個 Windows 10 和 Debian 10 的雙系統 | LCTT x X-CMD","titleTemplate":false,"description":"如何擁有一個 Windows 10 和 Debian 10 的雙系統 | LCTT (201911) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何擁有一個 Windows 10 和 Debian 10 的雙系統 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何擁有一個 Windows 10 和 Debian 10 的雙系統 | LCTT (201911) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201911/20191023 How to dual boot Windows 10 and Debian 10","title":"如何擁有一個 Windows 10 和 Debian 10 的雙系統","tag":"201911","desc":""},"relativePath":"201911/20191023 How to dual boot Windows 10 and Debian 10.md","filePath":"[post].md"}'),w={name:"201911/20191023 How to dual boot Windows 10 and Debian 10.md"};function b(c,t,d,m,g,h){const i=o("Link");return u(),s("div",null,[t[15]||(t[15]=l('<h1 id="如何擁有一個-windows-10-和-debian-10-的雙系統" tabindex="-1">如何擁有一個 Windows 10 和 Debian 10 的雙系統 <a class="header-anchor" href="#如何擁有一個-windows-10-和-debian-10-的雙系統" aria-label="Permalink to “如何擁有一個 Windows 10 和 Debian 10 的雙系統”">​</a></h1><p>在無數次勸説自己後，你終於做出了一個大膽的決定，試試 Linux。不過，在完全熟悉 Linux 之前，你依舊需要使用 Windows 10 系統。幸運的是，通過一個雙系統引導設置，能讓你在啓動時，選擇自己想要進入的系統。在這個指南中，你會看到如何 如何雙重引導 Windows 10 和 Debian 10。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/How-to-dual-boot-Windows-and-Debian10.jpg" alt="如何擁有一個 Windows 10 和 Debian 10 的雙系統"></p><h3 id="前提條件" tabindex="-1">前提條件 <a class="header-anchor" href="#前提條件" aria-label="Permalink to “前提條件”">​</a></h3><p>在開始之前，確保你滿足下列條件:</p><ul><li>一個 Debian 10 的可引導 USB 或 DVD</li><li>一個快速且穩定的網絡（為了安裝更新以及第三方軟件）</li></ul><p>另外，記得注意你係統的引導策略（UEFI 或 Legacy），需要確保兩個系統使用同一種引導模式。</p><h3 id="第一步-在硬盤上創建一個空餘分區" tabindex="-1">第一步：在硬盤上創建一個空餘分區 <a class="header-anchor" href="#第一步-在硬盤上創建一個空餘分區" aria-label="Permalink to “第一步：在硬盤上創建一個空餘分區”">​</a></h3><p>第一步，你需要在你的硬盤上創建一個空餘分區。之後，這將是我們安裝 Debian 系統的地方。為了實現這一目的，需要使用下圖所示的磁盤管理器：</p><p>同時按下 <code>Windows + R</code> 鍵，啓動“運行程序”。接下來，輸入 <code>diskmgmt.msc</code>，按回車鍵。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Launch-Run-dialogue.jpg" alt="啓動“運行程序”"></p><p>這會啓動“磁盤管理”窗口，它會顯示你 Windows 上所有已有磁盤。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Disk-management.jpg" alt="磁盤管理"></p><p>接下來，你需要為安裝的 Debian 系統創建空餘空間。為此，你需要縮小其中一個磁盤（卷）上的分區，從而創建一個未分配的新分區。在這個例子裏，我會從 D 盤中創建一個 30 GB 的新分區。</p><p>為了縮小一個卷，右鍵點擊它，然後選中選項 “<ruby>縮小<rt>Shrink volume...</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Shrink-volume.jpg" alt="縮小卷"></p><p>在彈出窗口中，定義你想縮小的空間大小。記住，這是將來要安裝 Debian 10 的磁盤空間。我選擇了 30000MB（大約 30 GB）。壓縮完成後，點擊“<ruby>縮小<rt>Shrink</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Shrink-space.jpg" alt="縮小空間"></p><p>在縮小操作結束後，你會看到一個如下圖所示的未分配分區：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Unallocated-partition.jpg" alt="未分配分區"></p><p>完美！現在可以準備開始安裝了。</p><h3 id="第二步-開始安裝-debian-10" tabindex="-1">第二步：開始安裝 Debian 10 <a class="header-anchor" href="#第二步-開始安裝-debian-10" aria-label="Permalink to “第二步：開始安裝 Debian 10”">​</a></h3><p>空餘分區已經創建好了，將你的可引導 USB 或安裝 DVD 插入電腦，重新啓動系統。記得更改 BIOS 中的引導順序，需要在啓動時按住功能鍵（通常，根據品牌不同，是 <code>F9</code>、<code>F10</code> 或 <code>F12</code> 中的某一個）。 這一步驟，對系統是否能進入安裝媒體來説，至關重要。保存 BIOS 設置，並重啓電腦。</p><p>如下圖所示，界面會顯示一個新的引導菜單：點擊 “Graphical install”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Graphical-Install-Debian10.jpg" alt="圖形化界面安裝"></p><p>下一步，選擇你的偏好語言，然後點擊 “<ruby>繼續<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Select-Language-Debian10.jpg" alt="設置語言-Debian10"></p><p>接着，選擇你的地區，點擊“<ruby>繼續<rt>Continue</rt></ruby>”。 根據地區，系統會自動選擇當地對應的時區。如果你無法找到你所對應的地區，將界面往下拉， 點擊“<ruby>其他<rt>Other</rt></ruby>”後，選擇相對應位置。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Select-location-Debain10.jpg" alt="選擇地區-Debain10"></p><p>而後，選擇你的鍵盤佈局。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Configure-Keyboard-layout-Debain10.jpg" alt="設置鍵盤-Debain10"></p><p>接下來，設置系統的主機名，點擊 “<ruby>繼續<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Set-hostname-Debian10.jpg" alt="設置主機名-Debian10"></p><p>下一步，確定域名。如果你的電腦不在域中，直接點擊 “<ruby>繼續<rt>Continue</rt></ruby>”按鈕。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Set-domain-name-Debian10.jpg" alt="設置域名-Debian10"></p><p>然後，如圖所示，設置 root 密碼，點擊 “<ruby>繼續<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Set-root-Password-Debian10.jpg" alt="設置 root 密碼-Debian10"></p><p>下一步驟，設置賬户的用户全名，點擊 “<ruby>繼續<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Specify-fullname-user-debain10.jpg" alt="設置用户全名-debain10"></p><p>接着，設置與此賬户相關聯的用户名。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Specify-username-Debian10.jpg" alt="指定用户名-Debian10"></p><p>下一步，設置用户密碼，點擊“<ruby>繼續<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Specify-user-password-Debian10.jpg" alt="設置用户密碼-Debian10"></p><p>然後，設置時區。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Configure-timezone-Debian10.jpg" alt="設置時區-Debian10"></p><p>這時，你要為 Debian10 安裝創建分區。如果你是新手用户，點擊菜單中的第一個選項，“<ruby>使用最大的連續空餘空間<rt>Use the largest continuous free space</rt></ruby>”，點擊“<ruby>繼續<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Use-largest-continuous-free-space-debian10.jpg" alt="使用最大的連續空餘空間-debian10"></p><p>不過，如果你對創建分區有所瞭解的話，選擇“<ruby>手動<rt>Manual</rt></ruby>” 選項，點擊 “<ruby>繼續<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Select-Manual-Debain10.jpg" alt="選擇手動-Debain10"></p><p>接着，選擇被標記為 “<ruby>空餘空間<rt>FREE SPACE</rt></ruby>” 的磁盤，點擊 “<ruby>繼續<rt>Continue</rt></ruby>” 。接下來，點擊“<ruby>創建新分區<rt>Create a new partition</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Create-new-partition-Debain10.jpg" alt="創建新分區-Debain10"></p><p>下一界面，首先確定交換空間大小。我的交換空間大小為 2GB，點擊 “<ruby>繼續<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Define-swap-space-debian10.jpg" alt="確定交換空間大小-debian10"></p><p>點擊下一界面的 “<ruby>主分區<rt>Primary</rt></ruby>”，點擊“<ruby>繼續<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Partition-Disks-Primary-Debain10.jpg" alt="磁盤主分區-Debian10"></p><p>選擇在磁盤 “<ruby>初始位置<rt>beginning</rt></ruby>” 創建新分區後，點擊繼續。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Start-at-the-beginning-Debain10.jpg" alt="在初始位置創建-Debain10"></p><p>選擇 “<ruby>Ext 4 日誌文件系統<rt>Ext 4 journaling file system</rt></ruby>”，點擊 “<ruby>繼續<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Select-Ext4-Journaling-system-debain10.jpg" alt="選擇 Ext4 日誌文件系統-debain10"></p><p>下個界面選擇“<ruby>交換空間<rt>swap space</rt></ruby>” ，點擊 “<ruby>繼續<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Select-swap-debain10.jpg" alt="選擇交換空間-debian10"></p><p>選中 “<ruby>完成此分區設置<rt>done setting the partition</rt></ruby>”，點擊 “<ruby>繼續<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Done-setting-partition-debian10.jpg" alt="完成此分區設置-debian10"></p><p>返回磁盤分區界面，點擊 “<ruby>空餘空間<rt>FREE SPACE</rt></ruby>”，點擊 “<ruby>繼續<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Click-Free-space-Debain10.jpg" alt="點擊空餘空間-Debain10"></p><p>為了讓自己能輕鬆一點，選中 “<ruby>自動為空餘空間分區<rt>Automatically partition the free space</rt></ruby>”後，點擊 “<ruby>繼續<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Automatically-partition-free-space-Debain10.jpg" alt="自動為空餘空間分區-Debain10"></p><p>接着點擊 “<ruby>將所有文件存儲在同一分區（新手用户推薦）<rt>All files in one partition (recommended for new users)</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/All-files-in-one-partition-debian10.jpg" alt="將所有文件存儲在同一分區-debian10"></p><p>最後， 點擊 “<ruby>完成分區設置，並將改動寫入磁盤<rt>Finish partitioning and write changes to disk</rt></ruby>” ，點擊 “<ruby>繼續<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Finish-partitioning-write-changes-to-disk.jpg" alt="完成分區設置，並將改動寫入磁盤"></p><p>確定你要將改動寫入磁盤，點擊 “<ruby>是<rt>Yes</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Write-changes-to-disk-Yes-Debian10.jpg" alt="將改動寫入磁盤-Debian10"></p><p>而後，安裝程序會開始安裝所有必要的軟件包。</p><p>當系統詢問是否要掃描其他 CD 時，選擇 “<ruby>否<rt>No</rt></ruby>” ，並點擊 “<ruby>繼續<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Scan-another-CD-No-Debain10.jpg" alt="掃描其他CD-No-Debain10"></p><p>接着，選擇離你最近的鏡像站點地區，點擊 “<ruby>繼續<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Debian-archive-mirror-country.jpg" alt="Debian-鏡像站點-國家"></p><p>然後，選擇最適合你的鏡像站點，點擊“<ruby>繼續<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Select-Debian-archive-mirror.jpg" alt="選擇鏡像站點"></p><p>如果你打算使用代理服務器，在下面輸入具體信息，沒有的話就留空，點擊 “<ruby>繼續<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Enter-proxy-details-debian10.jpg" alt="輸入代理信息-debian10"></p><p>隨着安裝進程的繼續， 你會被問到，是否想參加一個軟件包用途調查。你可以選擇任意一個選項，之後點擊“<ruby>繼續<rt>Continue</rt></ruby>”，我選擇了“<ruby>否<rt>No</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Participate-in-survey-debain10.jpg" alt="參與調查-debain10"></p><p>在軟件選擇窗口選中你想安裝的軟件包，點擊“<ruby>繼續<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Software-selection-debian10.jpg" alt="軟件選擇-debian10"></p><p>安裝程序會將選中的軟件一一安裝，在這期間，你可以去喝杯咖啡休息一下。</p><p>系統將會詢問你，是否要將 grub 的引導裝載程序安裝到主引導記錄表（MBR）上。點擊 “<ruby>是<rt>Yes</rt></ruby>”，而後點擊 “<ruby>繼續<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Install-grub-bootloader-debian10.jpg" alt="安裝-grub-bootloader-debian10"></p><p>接着，選中你想安裝 grub 的硬盤，點擊“<ruby>繼續<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Select-hard-drive-install-grub-Debian10.jpg" alt="選擇硬盤-安裝 grub-Debian10"></p><p>最後，安裝完成，直接點擊 “<ruby>繼續<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Installation-complete-reboot-debian10.jpg" alt="安裝完成-重新啓動-debian10"></p><p>你現在應該會有一個列出 Windows 和 Debian 的 grub 菜單。為了引導 Debian 系統，往下選擇 Debian。之後，你就能看見登錄界面。輸入密碼之後，按回車鍵。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Debian10-log-in.jpg" alt="Debian10-登錄"></p><p>這就完成了！這樣，你就擁有了一個全新的 Debian 10 和 Windows 10 雙系統。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Debian10-Buster-Details.jpg" alt="Debian10-Buster-Details"></p><hr>',98)),r("p",null,[t[1]||(t[1]=n("via: ",-1)),e(i,{href:"https://www.linuxtechi.com/dual-boot-windows-10-debian-10/"},{default:p(()=>[...t[0]||(t[0]=[n("https://www.linuxtechi.com/dual-boot-windows-10-debian-10/",-1)])]),_:1})]),r("p",null,[t[6]||(t[6]=n("作者：",-1)),e(i,{href:"https://www.linuxtechi.com/author/james/"},{default:p(()=>[...t[2]||(t[2]=[n("James Kiarie",-1)])]),_:1}),t[7]||(t[7]=n(" 選題：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:p(()=>[...t[3]||(t[3]=[n("lujun9972",-1)])]),_:1}),t[8]||(t[8]=n(" 譯者：",-1)),e(i,{href:"https://github.com/wenwensnow"},{default:p(()=>[...t[4]||(t[4]=[n("wenwensnow",-1)])]),_:1}),t[9]||(t[9]=n(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:p(()=>[...t[5]||(t[5]=[n("wxy",-1)])]),_:1})]),r("p",null,[t[12]||(t[12]=n("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[10]||(t[10]=[n("LCTT",-1)])]),_:1}),t[13]||(t[13]=n(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:p(()=>[...t[11]||(t[11]=[n("Linux中國",-1)])]),_:1}),t[14]||(t[14]=n(" 榮譽推出",-1))])])}const C=a(w,[["render",b]]);export{x as __pageData,C as default};
